import {
  newFieldId,
  newOptionValue,
  valueShape,
  type ArchivedFormField,
  type FormDefinition,
  type FormField,
  type FormFieldInput,
} from './form-definition.ts';

/**
 * Why an edit was refused:
 *
 * - `unknown_field`: an `id` that no version of the form ever had. Ids are
 *   generated by the server, so a client cannot pick one.
 * - `type_change`: a field changed to a type that stores another shape of
 *   value (for example `text` to `number`). Add a new field instead.
 * - `unknown_option`: an option `value` that the field does not have. New
 *   options are sent without a value.
 */
export type FormEditError = 'unknown_field' | 'type_change' | 'unknown_option';

/** Result of {@link applyFormEdit} and {@link restoreFormVersion}. */
export type FormEditResult =
  | { ok: true; definition: FormDefinition }
  | { ok: false; error: FormEditError; fieldIndex: number };

/** Every field the form ever had, by id: on the form or archived. */
const knownFields = (
  definition: FormDefinition,
): Map<string, FormField | ArchivedFormField> => {
  const known = new Map<string, FormField | ArchivedFormField>();
  for (const field of definition.archived) known.set(field.id, field);
  for (const field of definition.fields) known.set(field.id, field);
  return known;
};

const stripArchive = (field: FormField | ArchivedFormField): FormField => {
  if (!('lastVersion' in field)) return field;
  const { lastVersion: _lastVersion, ...rest } = field;
  return rest;
};

/**
 * The archived list of the next version: every field of `current` that is
 * not on the next form. Fields leaving the form now come first, with
 * `lastVersion` set to the current version.
 */
const nextArchive = (
  current: FormDefinition,
  currentVersion: number,
  nextFields: readonly FormField[],
): ArchivedFormField[] => {
  const onForm = new Set(nextFields.map((field) => field.id));
  const leaving = current.fields
    .filter((field) => !onForm.has(field.id))
    .map((field) => ({ ...field, lastVersion: currentVersion }));
  const stillArchived = current.archived.filter(
    (field) => !onForm.has(field.id),
  );
  return [...leaving, ...stillArchived];
};

/**
 * Builds the next version from the editor's fields.
 *
 * - A field without `id` is new and gets a fresh id that no version used.
 * - A field with `id` must be on the current form or archived (restoring an
 *   archived field keeps its id and its data). Its type may change only
 *   within the same value shape ({@link valueShape}).
 * - Fields of the current form that are missing are archived, never
 *   deleted.
 * - New options get a generated value; an option with a `value` must be one
 *   of the field's current options.
 *
 * @param current - The current definition, which the edit is based on.
 * @param currentVersion - Its version number.
 */
export const applyFormEdit = (
  current: FormDefinition,
  currentVersion: number,
  inputs: readonly FormFieldInput[],
): FormEditResult => {
  const known = knownFields(current);
  const fields: FormField[] = [];
  for (const [fieldIndex, input] of inputs.entries()) {
    let id = input.id;
    const previous = id === undefined ? undefined : known.get(id);
    if (id !== undefined) {
      if (!previous) return { ok: false, error: 'unknown_field', fieldIndex };
      if (valueShape(previous.type) !== valueShape(input.type)) {
        return { ok: false, error: 'type_change', fieldIndex };
      }
    } else {
      do id = newFieldId();
      while (known.has(id));
    }
    let options = input.options?.map((option) => ({
      value: option.value ?? '',
      label: option.label,
    }));
    if (options) {
      const previousValues = new Set(
        previous?.options?.map((option) => option.value) ?? [],
      );
      const used = new Set(previousValues);
      for (const option of options) {
        if (option.value === '') {
          let value: string;
          do value = newOptionValue();
          while (used.has(value));
          used.add(value);
          option.value = value;
        } else if (!previousValues.has(option.value)) {
          return { ok: false, error: 'unknown_option', fieldIndex };
        }
      }
    }
    const field: FormField = {
      id,
      type: input.type,
      label: input.label,
      required: input.required,
      showInList: input.showInList,
    };
    if (input.placeholder) field.placeholder = input.placeholder;
    if (input.hint) field.hint = input.hint;
    if (input.maxLength !== undefined) field.maxLength = input.maxLength;
    if (options) field.options = options;
    fields.push(field);
  }
  return {
    ok: true,
    definition: {
      fields,
      archived: nextArchive(current, currentVersion, fields),
    },
  };
};

/**
 * Builds the next version from the fields of an earlier version. Field ids
 * stay the same, so values stored under them line up again. Fields of the
 * current form that the earlier version did not have are archived.
 */
export const restoreFormVersion = (
  current: FormDefinition,
  currentVersion: number,
  earlier: FormDefinition,
): FormDefinition => {
  const fields = earlier.fields.map(stripArchive);
  return { fields, archived: nextArchive(current, currentVersion, fields) };
};

/** Every field the form ever had: the current fields, then archived ones. */
export const allKnownFields = (
  definition: FormDefinition,
): (FormField | ArchivedFormField)[] => [
  ...definition.fields,
  ...definition.archived,
];

const canonical = (value: unknown): unknown => {
  if (Array.isArray(value)) return value.map(canonical);
  if (typeof value === 'object' && value !== null) {
    return Object.fromEntries(
      Object.entries(value)
        .filter(([, entry]) => entry !== undefined)
        .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
        .map(([key, entry]) => [key, canonical(entry)]),
    );
  }
  return value;
};

/**
 * Returns whether two definitions are the same, ignoring the order of object
 * keys (stored JSON and edited fields list them in different orders).
 */
export const isSameDefinition = (
  a: FormDefinition,
  b: FormDefinition,
): boolean => JSON.stringify(canonical(a)) === JSON.stringify(canonical(b));
